SELECT rs.room_id AS roomId, CASE WHEN rs.room_id LIKE 'SUITE_%' THEN REPLACE(REPLACE(rs.room_id, 'SUITE_', ''), '_', ' ') ELSE COALESCE( ( SELECT CONCAT(COALESCE(area_name, ''), IF(area_name IS NULL OR area_name = '', '', ' '), room_name) FROM aro_access_log WHERE room_id = rs.room_id AND room_name IS NOT NULL LIMIT 1 ), rs.room_id ) END AS roomName, MAX(rs.max_capacity) AS maxCapacity, SUM(COALESCE(stat.currentPeople, 0)) AS currentPeople, SUM(COALESCE(stat.borrowedCards, 0)) AS borrowedCards FROM aro_room_settings rs LEFT JOIN ( SELECT e.room_id, e.room_name, e.area_name, COUNT(DISTINCT e.user_id) AS currentPeople, COUNT(DISTINCT CASE WHEN COALESCE(e.is_borrowed_card, 0) = 1 OR COALESCE(e.is_keep_card, 0) = 1 THEN e.user_id END) AS borrowedCards FROM aro_access_log e WHERE e.accessType = 1 AND CAST(e.create_time AS DATETIME) >= CAST(#{todayStart} AS DATETIME) AND CAST(e.create_time AS DATETIME) < CAST(#{todayEnd} AS DATETIME) AND NOT EXISTS ( SELECT 1 FROM aro_access_log out_log WHERE out_log.user_id = e.user_id AND out_log.room_id = e.room_id AND out_log.accessType IN (2, 3) AND CAST(out_log.create_time AS DATETIME) > CAST(e.create_time AS DATETIME) AND CAST(out_log.create_time AS DATETIME) >= CAST(#{todayStart} AS DATETIME) AND CAST(out_log.create_time AS DATETIME) < CAST(#{todayEnd} AS DATETIME) ) GROUP BY e.room_id, e.room_name, e.area_name ) stat ON ( rs.room_id = stat.room_id OR rs.room_id = stat.room_name OR ( rs.room_id LIKE 'SUITE_%' AND rs.room_id LIKE CONCAT('SUITE_', stat.area_name, '_%') AND stat.room_name LIKE CONCAT('%', REPLACE(rs.room_id, CONCAT('SUITE_', stat.area_name, '_'), ''), '%') ) )
rs.room_id = #{roomId}
GROUP BY rs.room_id

