SELECT log.user_id AS userId, log.name AS userName, log.project_group_names AS groupName, log.area_name AS areaName, log.room_name AS roomName, log.room_id AS roomId FROM aro_access_log log WHERE log.accessType = 1 AND log.user_id IN
#{uid}
AND CAST(log.create_time AS DATETIME) >= CAST(#{todayStart} AS DATETIME) AND CAST(log.create_time AS DATETIME) < CAST(#{todayEnd} AS DATETIME) AND NOT EXISTS ( SELECT 1 FROM aro_access_log out_log WHERE out_log.user_id = log.user_id AND out_log.room_id = log.room_id AND out_log.accessType IN (2, 3) AND CAST(out_log.create_time AS DATETIME) > CAST(log.create_time AS DATETIME) ) ORDER BY log.create_time DESC
